INSERT INTO public.factors OVERRIDING SYSTEM VALUE VALUES ('c1835e8c-5b5b-4d66-b3a3-e11790ad882c', 59, 'global', 'Candida auris as a rapidly emerging multidrug-resistant fungal threat', 'The number of reported clinical cases of Candida auris in the United States increased nearly five-fold from 2019 to 2022. C. auris is a yeast that spreads in healthcare facilities, is often resistant to antifungal medications, and can cause severe illness. WHO identifies it as a particular concern globally.', '[-0.20410156,1.9296875,1.640625,-1.421875,3.1875,4.34375,-3.109375,-5.1875,-2.65625,5.9375,-3.828125,-2.40625,6.34375,2.515625,-0.41015625,-3.296875,3.46875,-2.3125,-3.0625,1.140625,5.96875,-0.87890625,-0.006225586,-0.028930664,-0.8671875,2.796875,-1.8203125,-2.015625,-0.26757812,-1.265625,-1.84375,3.671875,-1.5625,2.046875,-1.3046875,3.3125,0.83984375,-2.09375,-0.4375,1.3828125,-2.484375,-0.25976562,-0.52734375,-1.390625,2.515625,1.28125,-1,-1.6875,0.8046875,1.8125,3.609375,-1.859375,-0.056640625,1.1640625,0.6875,0.47265625,2.765625,1.671875,-1.5625,-1.2734375,-5.03125,1.7265625,-0.92578125,2.9375,-2.671875,-1.7109375,0.89453125,-1.84375,0.72265625,-0.21875,-0.609375,-0.8359375,3.140625,-0.2265625,-0.66796875,2.875,-2.421875,3.234375,2.5625,1.1484375,-1.8671875,-3.3125,2.515625,1.5703125,1.078125,-2.359375,0.36132812,1.0703125,-5.0625,1.375,-1.1640625,2.015625,1.9296875,1.9296875,2.140625,-4.6875,1.9921875,-2.984375,0.14160156,1.390625,1.1171875,1.7578125,-2.28125,-2.09375,-0.625,-3.703125,-1.4140625,0.94140625,0.75,0.36914062,-2.46875,-0.65625,0.19921875,3.765625,-1.6796875,1.78125,1.6953125,0.94140625,3.328125,4.84375,-0.056640625,-2.015625,1.7734375,0.67578125,2.078125,-0.234375,-4.21875,1.0390625,-3.53125,3.1875,0.19921875,-1.28125,2.8125,-3.078125,0.03125,0.19726562,2.78125,0.8515625,-5.875,-1.46875,-0.45703125,-2.578125,3.015625,1.2734375,-1.03125,2.5,-2.390625,2.546875,0.43945312,1.3984375,4.5625,-0.46289062,-1.34375,1.546875,4.09375,-2.125,-0.12158203,2.390625,-1.3359